//! Android-specific generated files (M5): VectorDrawables from SVG icons,
//! the icon id table used by the Android host's `eraIcon`, the app name,
//! and the list of assets to package.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use era_ir::ir::{App, AssetKind};

use crate::GENERATED_HEADER;
use crate::kotlin::string;
use crate::svg;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AndroidOutput {
    /// `(path relative to the Android project, contents)`, sorted.
    pub files: Vec<(String, String)>,
    /// `(path relative to Assets/, path relative to the Android project)`.
    pub copies: Vec<(String, String)>,
}

/// A problem converting one asset.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetProblem {
    /// Asset path relative to `Assets/`.
    pub path: String,
    pub message: String,
}

/// `Icons/arrow-left.svg` -> `era_icon_icons_arrow_left` (a valid Android
/// resource name: lowercase letters, digits and `_`).
pub fn icon_resource_name(path: &str) -> String {
    let stem = path.rsplit_once('.').map_or(path, |(s, _)| s);
    let mut out = String::from("era_icon_");
    let mut last_underscore = true;
    for c in stem.chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c.to_ascii_lowercase());
            last_underscore = false;
        } else if !last_underscore {
            out.push('_');
            last_underscore = true;
        }
    }
    out.trim_end_matches('_').to_string()
}

/// `1.2.3` -> `10203` (Android `versionCode`).
pub fn version_code(version: &str) -> u32 {
    let parts: Vec<u32> = version.split('.').map(|p| p.parse().unwrap_or(0)).collect();
    parts.first().copied().unwrap_or(0) * 10_000
        + parts.get(1).copied().unwrap_or(0) * 100
        + parts.get(2).copied().unwrap_or(0)
}

fn xml_text(s: &str) -> String {
    // Android string resources also treat `'`, `"` and `@`/`?` at the start specially.
    let mut out = s
        .replace('\\', "\\\\")
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('\'', "\\'")
        .replace('"', "\\\"");
    if out.starts_with('@') || out.starts_with('?') {
        out.insert(0, '\\');
    }
    out
}

/// Generate Android resources. `read_asset` returns the text of a file in
/// `Assets/` (used for SVG icons).
pub fn generate(
    app: &App,
    package: &str,
    read_asset: impl Fn(&str) -> Result<String, String>,
) -> Result<AndroidOutput, Vec<AssetProblem>> {
    let mut files = Vec::new();
    let mut copies = Vec::new();
    let mut problems = Vec::new();
    let mut icon_ids: BTreeMap<String, String> = BTreeMap::new();
    let mut used_names: BTreeMap<String, usize> = BTreeMap::new();

    for a in &app.assets {
        match a.kind {
            AssetKind::Icon => {
                let base = icon_resource_name(&a.path);
                let n = used_names.entry(base.clone()).or_insert(0);
                *n += 1;
                let name = if *n == 1 { base } else { format!("{base}_{n}") };
                match read_asset(&a.path).and_then(|text| svg::to_vector_drawable(&text)) {
                    Ok(xml) => {
                        files.push((format!("src/main/res/drawable/{name}.xml"), xml));
                        icon_ids.insert(a.path.clone(), name);
                    }
                    Err(message) => problems.push(AssetProblem {
                        path: a.path.clone(),
                        message,
                    }),
                }
            }
            AssetKind::Image | AssetKind::Font => {
                copies.push((a.path.clone(), format!("src/main/assets/{}", a.path)));
            }
        }
    }
    if !problems.is_empty() {
        return Err(problems);
    }

    let mut ids = format!(
        "{GENERATED_HEADER}\npackage {package}\n\nimport {}.R\n\n",
        app.id
    );
    ids.push_str("/** SVG icon path -> generated VectorDrawable resource. */\nval EraIconIds: Map<String, Int> = mapOf(\n");
    for (path, name) in &icon_ids {
        let _ = writeln!(ids, "    {} to R.drawable.{name},", string(path));
    }
    ids.push_str(")\n");
    files.push((
        format!(
            "src/main/kotlin/{}/EraIconIds.kt",
            package.replace('.', "/")
        ),
        ids,
    ));

    files.push((
        "src/main/res/values/strings.xml".into(),
        format!(
            "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!-- Generated by ERA. Do not edit. -->\n<resources>\n    <string name=\"app_name\">{}</string>\n</resources>\n",
            xml_text(&app.name)
        ),
    ));
    files.sort();
    copies.sort();
    Ok(AndroidOutput { files, copies })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resource_names() {
        assert_eq!(icon_resource_name("Icons/star.svg"), "era_icon_icons_star");
        assert_eq!(
            icon_resource_name("Icons/Arrow-Left 2.svg"),
            "era_icon_icons_arrow_left_2"
        );
        assert_eq!(
            icon_resource_name("Icons/sub/x__y.svg"),
            "era_icon_icons_sub_x_y"
        );
    }

    #[test]
    fn version_codes() {
        assert_eq!(version_code("0.1.0"), 100);
        assert_eq!(version_code("1.2.3"), 10203);
        assert_eq!(version_code("2.0.15"), 20015);
    }

    #[test]
    fn app_names_are_escaped_for_resources() {
        assert_eq!(
            xml_text("Tom & Jerry's \"App\""),
            "Tom &amp; Jerry\\'s \\\"App\\\""
        );
        assert_eq!(xml_text("@home"), "\\@home");
    }
}
